@Suppress("DEPRECATION")
class HardwareModule(private val ctx:ReactApplicationContext):ReactContextBaseJavaModule(ctx),LifecycleEventListener,SensorEventListener {
 private val main=Handler(Looper.getMainLooper())
 private val sensors=ctx.getSystemService(Context.SENSOR_SERVICE) as SensorManager
 private val wifi=ctx.applicationContext.getSystemService(Context.WIFI_SERVICE) as WifiManager
 private val alive=AtomicBoolean(false)
 private var record:AudioRecord?=null
 private var track:AudioTrack?=null
 private var audioThread:Thread?=null
 private var camera:Camera?=null
 private var texture:SurfaceTexture?=null
 private var previous:ByteArray?=null
 private var handModel:HandLandmarker?=null
 private var lastCamera=0L
 private var wifiTask:Runnable?=null
 private var hot:WifiManager.LocalOnlyHotspotReservation?=null
 private var hotspotRequested=false
 private var bleCallback:ScanCallback?=null
 private var lastSensor=mutableMapOf<Int,Long>()
 init{ctx.addLifecycleEventListener(this)}
 override fun getName()="GMHardware"
 private fun permitted(p:String)=ctx.checkSelfPermission(p)==PackageManager.PERMISSION_GRANTED
 private fun emit(kind:String,data:WritableMap){data.putString("kind",kind);data.putDouble("timestamp",System.currentTimeMillis().toDouble());if(ctx.hasActiveReactInstance())ctx.getJSModule(DeviceEventManagerModule.RCTDeviceEventEmitter::class.java).emit("GMHardwareSample",data)}
 private fun error(kind:String,e:Throwable){val m=Arguments.createMap();m.putString("error",e.message?:e.javaClass.simpleName);emit(kind,m)}
 @ReactMethod fun addListener(name:String){}
 @ReactMethod fun removeListeners(n:Double){}
 @ReactMethod fun capabilities(p:Promise){try{
  val m=Arguments.createMap();m.putString("model",Build.MODEL);m.putString("manufacturer",Build.MANUFACTURER);m.putString("device",Build.DEVICE);m.putInt("sdk",Build.VERSION.SDK_INT);m.putString("os",Build.VERSION.RELEASE)
  val arr=Arguments.createArray();for(s in sensors.getSensorList(Sensor.TYPE_ALL)){val x=Arguments.createMap();x.putString("name",s.name);x.putString("vendor",s.vendor);x.putInt("type",s.type);x.putDouble("resolution",s.resolution.toDouble());x.putDouble("maxRange",s.maximumRange.toDouble());x.putInt("minDelayUs",s.minDelay);x.putDouble("powerMa",s.power.toDouble());arr.pushMap(x)};m.putArray("sensors",arr)
  val am=ctx.getSystemService(Context.AUDIO_SERVICE) as AudioManager;val a=Arguments.createMap();a.putString("outputSampleRate",am.getProperty(AudioManager.PROPERTY_OUTPUT_SAMPLE_RATE));a.putString("outputFramesPerBuffer",am.getProperty(AudioManager.PROPERTY_OUTPUT_FRAMES_PER_BUFFER));a.putBoolean("microphone",ctx.packageManager.hasSystemFeature(PackageManager.FEATURE_MICROPHONE));a.putBoolean("recordPermission",permitted(Manifest.permission.RECORD_AUDIO));a.putString("declaredMicrophoneNearUltrasound",am.getProperty("android.media.property.SUPPORT_MIC_NEAR_ULTRASOUND"));a.putString("declaredSpeakerNearUltrasound",am.getProperty("android.media.property.SUPPORT_SPEAKER_NEAR_ULTRASOUND"));a.putString("declaredUnprocessedSource",am.getProperty(AudioManager.PROPERTY_SUPPORT_AUDIO_SOURCE_UNPROCESSED));a.putBoolean("ultrasoundCapabilityMeasured",false)
  val trials=Arguments.createArray();for(rate in listOf(16000,24000,44100,48000,96000)){val t=Arguments.createMap();val bytes=AudioRecord.getMinBufferSize(rate,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);t.putInt("requestedRate",rate);t.putInt("minBufferBytes",bytes);t.putBoolean("configurationDeclarationAccepted",bytes>0);trials.pushMap(t)};a.putArray("pcmConfigurationDeclarations",trials);a.putString("rateLimitation","getMinBufferSize declarations are not physical sampling-clock or bandwidth measurements")
  val inputs=Arguments.createArray();for(device in am.getDevices(AudioManager.GET_DEVICES_INPUTS)){val d=Arguments.createMap();d.putString("name",device.productName.toString());d.putInt("type",device.type);val rates=Arguments.createArray();device.sampleRates.forEach{rates.pushInt(it)};d.putArray("reportedSampleRates",rates);d.putString("emptyRatesMeaning","Unspecified rate support, not zero capability");inputs.pushMap(d)};a.putArray("audioInputDevices",inputs)
  if(Build.VERSION.SDK_INT>=28&&permitted(Manifest.permission.RECORD_AUDIO)){try{val micList=Arguments.createArray();for(mic in am.microphones){val d=Arguments.createMap();d.putString("description",mic.description);d.putInt("type",mic.type);d.putInt("locationClass",mic.location);d.putInt("directionality",mic.directionality);if(mic.sensitivity.isFinite())d.putDouble("declaredSensitivityDb",mic.sensitivity.toDouble());val response=Arguments.createArray();for(point in mic.frequencyResponse.take(64)){if(point.first.isFinite()&&point.second.isFinite()){val row=Arguments.createArray();row.pushDouble(point.first.toDouble());row.pushDouble(point.second.toDouble());response.pushArray(row)}};d.putArray("declaredFrequencyResponseHzDb",response);micList.pushMap(d)};a.putArray("microphoneDeclarations",micList)}catch(e:Throwable){a.putString("microphoneDetailsError",e.message)}};m.putMap("audio",a)
  val c=Arguments.createMap();c.putInt("count",Camera.getNumberOfCameras());c.putBoolean("permission",permitted(Manifest.permission.CAMERA));c.putString("reference","MediaPipe normalized image-plane hand landmarks plus frame-difference reference; no measured depth");m.putMap("camera",c)
  val b=Arguments.createMap();b.putBoolean("supported",ctx.packageManager.hasSystemFeature(PackageManager.FEATURE_BLUETOOTH_LE));val adapter=(ctx.getSystemService(Context.BLUETOOTH_SERVICE) as BluetoothManager).adapter;b.putBoolean("connectPermission",Build.VERSION.SDK_INT<31||permitted(Manifest.permission.BLUETOOTH_CONNECT));if(Build.VERSION.SDK_INT<31||permitted(Manifest.permission.BLUETOOTH_CONNECT))b.putBoolean("enabled",adapter?.isEnabled?:false);m.putMap("ble",b)
  m.putMap("wifi",wifiSnapshot());val bm=ctx.getSystemService(Context.BATTERY_SERVICE) as BatteryManager;m.putInt("batteryPercent",bm.getIntProperty(BatteryManager.BATTERY_PROPERTY_CAPACITY));m.putBoolean("charging",bm.isCharging);val pm=ctx.getSystemService(Context.POWER_SERVICE) as PowerManager;if(Build.VERSION.SDK_INT>=29)m.putInt("thermalStatus",pm.currentThermalStatus);m.putBoolean("powerSave",pm.isPowerSaveMode);p.resolve(m)
 }catch(e:Throwable){p.reject("CAPABILITIES",e)}}
 private fun wifiSnapshot():WritableMap{
  val m=Arguments.createMap();m.putBoolean("enabled",wifi.isWifiEnabled);m.putBoolean("rttFeature",ctx.packageManager.hasSystemFeature(PackageManager.FEATURE_WIFI_RTT));m.putBoolean("csiPublicApi",false);m.putString("csiStatus","not exposed by documented Android APIs; external CSI device required")
  m.putBoolean("nearbyPermission",Build.VERSION.SDK_INT<33||permitted(Manifest.permission.NEARBY_WIFI_DEVICES));m.putBoolean("locationPermission",permitted(Manifest.permission.ACCESS_FINE_LOCATION));if(Build.VERSION.SDK_INT>=30)m.putBoolean("scanThrottleEnabled",wifi.isScanThrottleEnabled);m.putString("scanPolicy","No repeated scans. Connection RSSI sampled 1 Hz for at most 30 seconds.")
  m.putBoolean("localOnlyHotspotApi",Build.VERSION.SDK_INT>=26);m.putBoolean("hotspotActive",hot!=null);m.putString("hotspotLimitation","Local-only hotspot creates a local network; no tethering toggle or hidden APIs. RTT measures compatible device range, never hand range.")
  try{val cm=ctx.getSystemService(Context.CONNECTIVITY_SERVICE) as ConnectivityManager;val cap=cm.getNetworkCapabilities(cm.activeNetwork);m.putBoolean("connected",cap?.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)==true);val i=wifi.connectionInfo;m.putInt("rssiDbm",i.rssi);m.putInt("frequencyMhz",i.frequency);m.putInt("linkSpeedMbps",i.linkSpeed);if(Build.VERSION.SDK_INT>=29){m.putInt("rxLinkSpeedMbps",i.rxLinkSpeedMbps);m.putInt("txLinkSpeedMbps",i.txLinkSpeedMbps)};m.putString("supplicantState",i.supplicantState.toString())}catch(e:SecurityException){m.putString("connectionError","permission required; connection fields may be redacted")};return m
 }
 @ReactMethod fun startSensors(p:Promise){try{for(type in listOf(Sensor.TYPE_ACCELEROMETER,Sensor.TYPE_GYROSCOPE,Sensor.TYPE_MAGNETIC_FIELD,Sensor.TYPE_PROXIMITY,Sensor.TYPE_LIGHT)){sensors.getDefaultSensor(type)?.let{sensors.registerListener(this,it,100000)}};main.postDelayed({sensors.unregisterListener(this)},60000);p.resolve(true)}catch(e:Throwable){p.reject("SENSORS",e)}}
 override fun onSensorChanged(e:SensorEvent){val now=SystemClock.elapsedRealtime();if(now-(lastSensor[e.sensor.type]?:0)<100)return;lastSensor[e.sensor.type]=now;val m=Arguments.createMap();m.putInt("sensorType",e.sensor.type);m.putString("name",e.sensor.name);m.putInt("accuracy",e.accuracy);val a=Arguments.createArray();e.values.forEach{a.pushDouble(it.toDouble())};m.putArray("values",a);emit("sensor",m)}
 override fun onAccuracyChanged(s:Sensor?,a:Int){}
 @ReactMethod fun startWifi(p:Promise){main.post{wifiTask?.let{main.removeCallbacks(it)};val end=SystemClock.elapsedRealtime()+30000;val task=object:Runnable{override fun run(){if(SystemClock.elapsedRealtime()>end){wifiTask=null;return};try{emit("wifi",wifiSnapshot())}catch(e:Throwable){error("wifi",e)};main.postDelayed(this,1000)}};wifiTask=task;main.post(task)};p.resolve(true)}
 @ReactMethod fun startHotspot(p:Promise){if(Build.VERSION.SDK_INT<26){p.reject("HOTSPOT","API 26 required");return};main.post{if(hot!=null||hotspotRequested){p.resolve(true);return@post};try{hotspotRequested=true;wifi.startLocalOnlyHotspot(object:WifiManager.LocalOnlyHotspotCallback(){override fun onStarted(r:WifiManager.LocalOnlyHotspotReservation){if(!hotspotRequested){r.close();return};hot=r;hotspotRequested=false;val m=Arguments.createMap();m.putBoolean("active",true);m.putString("note","Credentials deliberately not retained or transmitted");emit("hotspot",m);main.postDelayed({if(hot===r){r.close();hot=null}},30000)};override fun onStopped(){hot=null;hotspotRequested=false};override fun onFailed(reason:Int){hotspotRequested=false;val m=Arguments.createMap();m.putInt("failureReason",reason);emit("hotspot",m)}},main);p.resolve(true)}catch(e:Throwable){hotspotRequested=false;p.reject("HOTSPOT",e)}}}
 @ReactMethod fun startBle(p:Promise){if(Build.VERSION.SDK_INT>=31&&!permitted(Manifest.permission.BLUETOOTH_SCAN)){p.reject("PERMISSION","Bluetooth scan permission required");return};try{val scanner=(ctx.getSystemService(Context.BLUETOOTH_SERVICE) as BluetoothManager).adapter?.bluetoothLeScanner?:throw IllegalStateException("BLE disabled or unavailable");bleCallback?.let{scanner.stopScan(it)};var count=0;var lastEmit=0L;val callback=object:ScanCallback(){override fun onScanResult(t:Int,r:ScanResult){count++;if(count>=1000){scanner.stopScan(this);return};val now=SystemClock.elapsedRealtime();if(now-lastEmit<100)return;lastEmit=now;val m=Arguments.createMap();m.putInt("observations",count);m.putInt("rssiDbm",r.rssi);m.putString("privacy","No addresses or advertisements retained");emit("ble",m)};override fun onScanFailed(code:Int){val m=Arguments.createMap();m.putInt("failureCode",code);emit("ble",m)}};bleCallback=callback;scanner.startScan(callback);main.postDelayed({try{scanner.stopScan(callback)}catch(_:Throwable){};if(bleCallback===callback)bleCallback=null},10000);p.resolve(true)}catch(e:Throwable){p.reject("BLE",e)}}
 @ReactMethod fun startAudio(durationMs:Double,amplitude:Double,frequencyHz:Double,p:Promise){if(!permitted(Manifest.permission.RECORD_AUDIO)){p.reject("PERMISSION","Microphone permission required");return};if(alive.get()||audioThread?.isAlive==true){p.reject("BUSY","Audio experiment already running");return};alive.set(true);val duration=AcquisitionPolicy.duration(durationMs);val gain=AcquisitionPolicy.amplitude(amplitude);val freq=AcquisitionPolicy.frequency(frequencyHz);audioThread=Thread{
  try{var rate=48000;var min=AudioRecord.getMinBufferSize(rate,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);if(min<=0){rate=44100;min=AudioRecord.getMinBufferSize(rate,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT)};require(min>0){"No PCM recording rate supported"};val n=max(min,2048);val audioManager=ctx.getSystemService(Context.AUDIO_SERVICE) as AudioManager;val captureSource=if(audioManager.getProperty(AudioManager.PROPERTY_SUPPORT_AUDIO_SOURCE_UNPROCESSED)=="true")MediaRecorder.AudioSource.UNPROCESSED else MediaRecorder.AudioSource.VOICE_RECOGNITION;val rec=AudioRecord(captureSource,rate,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT,n*2);record=rec;require(rec.state==AudioRecord.STATE_INITIALIZED){"AudioRecord initialization failed"};val outMin=AudioTrack.getMinBufferSize(rate,AudioFormat.CHANNEL_OUT_MONO,AudioFormat.ENCODING_PCM_16BIT);val out=AudioTrack(AudioManager.STREAM_MUSIC,rate,AudioFormat.CHANNEL_OUT_MONO,AudioFormat.ENCODING_PCM_16BIT,max(n*2,outMin),AudioTrack.MODE_STREAM);track=out;require(out.state==AudioTrack.STATE_INITIALIZED){"AudioTrack initialization failed"};synchronized(this){if(!alive.get())throw IllegalStateException("Experiment cancelled before start");rec.startRecording();out.play()};val samples=ShortArray(1024);val tone=ShortArray(1024);var frame=0L;var total=0L;val start=SystemClock.elapsedRealtime();var last=start
   while(alive.get()&&SystemClock.elapsedRealtime()-start<duration){for(j in tone.indices){tone[j]=(sin(2*PI*freq*(frame+j)/rate)*gain*32767).toInt().toShort()};frame+=tone.size;out.write(tone,0,tone.size,AudioTrack.WRITE_NON_BLOCKING);val got=rec.read(samples,0,samples.size,AudioRecord.READ_BLOCKING);if(got<=0)break;total+=got;val now=SystemClock.elapsedRealtime();if(now-last>=100){var sum=0.0;var peak=0.0;for(j in 0 until got){val v=samples[j]/32768.0;sum+=v*v;peak=max(peak,abs(v))};val m=Arguments.createMap();m.putDouble("rms",sqrt(sum/got));m.putDouble("peak",peak);m.putInt("requestedSampleRate",rate);m.putInt("configuredRecordRate",rec.sampleRate);m.putInt("configuredPlaybackRate",out.sampleRate);m.putDouble("effectiveReadSamplesPerSecond",total*1000.0/max(1,now-start));m.putDouble("elapsedMs",(now-start).toDouble());val captureStamp=AudioTimestamp();val stampStatus=rec.getTimestamp(captureStamp,AudioTimestamp.TIMEBASE_MONOTONIC);m.putInt("captureTimestampStatus",stampStatus);if(stampStatus==AudioRecord.SUCCESS){m.putDouble("captureFramePosition",captureStamp.framePosition.toDouble());m.putDouble("captureMonotonicTimeNs",captureStamp.nanoTime.toDouble())};val playStamp=AudioTimestamp();if(out.getTimestamp(playStamp)){m.putDouble("playbackFramePosition",playStamp.framePosition.toDouble());m.putDouble("playbackMonotonicTimeNs",playStamp.nanoTime.toDouble())};m.putString("timestampLimitation","Platform frame timestamps are diagnostics; no loopback latency or clock accuracy calibrated");m.putDouble("playbackAmplitude",gain);m.putDouble("toneHz",freq);m.putString("captureSource",if(captureSource==MediaRecorder.AudioSource.UNPROCESSED)"UNPROCESSED" else "VOICE_RECOGNITION");m.putString("processingLimitation","Declared source does not guarantee absence of hardware/vendor DSP");m.putString("evidence","live PCM summary; no acoustic position or physical rate guarantee");emit("audio",m);last=now}}
  }catch(e:Throwable){error("audio",e)}finally{stopAudio();val m=Arguments.createMap();m.putBoolean("stopped",true);emit("audio",m)}
 };audioThread?.start();p.resolve(true)}
 @Synchronized private fun stopAudio(){alive.set(false);val r=record;record=null;try{r?.stop()}catch(_:Throwable){};try{r?.release()}catch(_:Throwable){};val t=track;track=null;try{t?.stop()}catch(_:Throwable){};try{t?.release()}catch(_:Throwable){}}
 @ReactMethod fun startCamera(p:Promise){if(!permitted(Manifest.permission.CAMERA)){p.reject("PERMISSION","Camera permission required");return};main.post{try{stopCamera();try{handModel=HandLandmarker.createFromOptions(ctx,HandLandmarker.HandLandmarkerOptions.builder().setBaseOptions(BaseOptions.builder().setModelAssetPath("hand_landmarker.task").build()).setRunningMode(RunningMode.IMAGE).setNumHands(1).setMinHandDetectionConfidence(0.6f).setMinHandPresenceConfidence(0.6f).build())}catch(e:Throwable){error("camera-model",e)};var cameraId=0;for(i in 0 until Camera.getNumberOfCameras()){val info=Camera.CameraInfo();Camera.getCameraInfo(i,info);if(info.facing==Camera.CameraInfo.CAMERA_FACING_FRONT){cameraId=i;break}};val info=Camera.CameraInfo();Camera.getCameraInfo(cameraId,info);val cam=Camera.open(cameraId);camera=cam;val par=cam.parameters;val size=par.supportedPreviewSizes.minByOrNull{abs(it.width*it.height-640*480)}?:throw IllegalStateException("No preview size");par.setPreviewSize(size.width,size.height);par.previewFormat=ImageFormat.NV21;cam.parameters=par;texture=SurfaceTexture(0);cam.setPreviewTexture(texture);val end=SystemClock.elapsedRealtime()+30000;cam.setPreviewCallback{data,_ ->val now=SystemClock.elapsedRealtime();if(now>end){stopCamera();return@setPreviewCallback};if(now-lastCamera<120)return@setPreviewCallback;lastCamera=now;val old=previous;var weight=0.0;var sx=0.0;var sy=0.0;val count=size.width*size.height;if(old!=null&&old.size>=count){for(y in 0 until size.height step 8)for(x in 0 until size.width step 8){val i=y*size.width+x;val d=abs((data[i].toInt()and 255)-(old[i].toInt()and 255));if(d>15){weight+=d;sx+=x*d;sy+=y*d}};val m=Arguments.createMap();m.putDouble("motionEnergy",weight/(count/64.0*255.0));if(weight>0){m.putDouble("x",sx/weight/size.width);m.putDouble("y",sy/weight/size.height)};m.putString("coordinateFrame","camera-image-normalized");m.putBoolean("handPresent",false);m.putString("tracker","frame-difference");handModel?.let{model -> try{val jpeg=ByteArrayOutputStream();YuvImage(data,ImageFormat.NV21,size.width,size.height,null).compressToJpeg(Rect(0,0,size.width,size.height),80,jpeg);val bytes=jpeg.toByteArray();val bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.size);val image=BitmapImageBuilder(bitmap).build();try{val result=model.detect(image);m.putString("tracker","MediaPipe HandLandmarker");val points=result.landmarks().firstOrNull();if(points!=null){m.putBoolean("handPresent",true);m.putInt("landmarkCount",points.size);m.putDouble("x",points[8].x().toDouble());m.putDouble("y",points[8].y().toDouble());m.putString("referencePoint","index fingertip");m.putDouble("confidenceHeuristic",0.7)}}finally{image.close();bitmap.recycle()}}catch(e:Throwable){m.putString("trackingError",e.message)}};m.putString("coordinateOrientation",if(info.facing==Camera.CameraInfo.CAMERA_FACING_FRONT)"raw front-camera image axes" else "raw back-camera image axes");m.putString("limitation","Normalized image-plane landmarks; no measured depth or metric range; confidence heuristic not calibrated");emit("camera",m)};previous=data.copyOf(count)};cam.startPreview();p.resolve(true)}catch(e:Throwable){stopCamera();p.reject("CAMERA",e)}}}
 private fun stopCamera(){try{camera?.setPreviewCallback(null);camera?.stopPreview();camera?.release()}catch(_:Throwable){};camera=null;texture?.release();texture=null;previous=null;try{handModel?.close()}catch(_:Throwable){};handModel=null}
 private fun stopAll(){stopAudio();sensors.unregisterListener(this);main.post{wifiTask?.let{main.removeCallbacks(it)};wifiTask=null;hotspotRequested=false;hot?.close();hot=null;stopCamera();try{val scanner=(ctx.getSystemService(Context.BLUETOOTH_SERVICE) as BluetoothManager).adapter?.bluetoothLeScanner;bleCallback?.let{scanner?.stopScan(it)}}catch(_:Throwable){};bleCallback=null}}
 @ReactMethod fun stop(p:Promise){stopAll();p.resolve(true)}
 override fun onHostResume(){}
 override fun onHostPause(){stopAll()}
 override fun onHostDestroy(){stopAll()}
 override fun invalidate(){stopAll();ctx.removeLifecycleEventListener(this);super.invalidate()}
}
